{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= len(A) <= 30",
      "description": "The length of the input string A is between 1 and 30 characters."
    },
    {
      "id": "P2",
      "expression": "all(c in 'abcdefghijklmnopqrstuvwxyz' for c in A)",
      "description": "All characters in the input string A are lowercase Latin letters."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output) > 0",
      "description": "The output is a non-empty string."
    },
    {
      "id": "Q2",
      "expression": "len(output) <= len(A)",
      "description": "The length of the output string is not greater than the length of the input string."
    },
    {
      "id": "Q3",
      "expression": "all(output in A for i in range(1, len(A) // len(output) + 1) if A.startswith(output * i))",
      "description": "The output string is a substring of A and it is repeated the most times in A."
    },
    {
      "id": "Q4",
      "expression": "not any(all(output in A for i in range(1, len(A) // len(other) + 1) if A.startswith(other * i)) and len(output) < len(other) for other in set(A) if other != output)",
      "description": "If there are multiple substrings with the same maximal repeat time, the output string has the maximal length."
    },
    {
      "id": "Q5",
      "expression": "not any(all(output in A for i in range(1, len(A) // len(other) + 1) if A.startswith(other * i)) and output > other for other in set(A) if other != output)",
      "description": "If there is a tie in length, the output string is alphabetically later than any other substring with the same repeat time."
    }
  ],
  "invariants": []
}
